// MARK: Waiters

@available(macOS 10.15, iOS 13.0, tvOS 13.0, watchOS 6.0, *)
extension Continuum {
    /// Waiter for operation ``getCodeScan(_:logger:)``.
    ///
    /// - Parameters:
    ///   - input: Input for operation
    ///   - logger: Logger used for logging
    @inlinable
    public func waitUntilCodeScanSucceeded(
        _ input: GetCodeScanInput,
        maxWaitTime: TimeAmount? = nil,
        logger: Logger = AWSClient.loggingDisabled
    ) async throws {
        let waiter = AWSClient.Waiter<GetCodeScanInput, _>(
            acceptors: [
                .init(state: .success, matcher: try! JMESPathMatcher("scan.status", expected: "SUCCEEDED")),
                .init(state: .failure, matcher: try! JMESPathMatcher("scan.status", expected: "FAILED")),
            ],
            minDelayTime: .seconds(60),
            maxDelayTime: .seconds(28800),
            command: self.getCodeScan
        )
        return try await self.client.waitUntil(input, waiter: waiter, maxWaitTime: maxWaitTime, logger: logger)
    }
    /// Waiter for operation ``getCodeScan(_:logger:)``.
    ///
    /// - Parameters:
    ///   - environmentId: Environment that owns the scan.
    ///   - scanRunId: Scan to retrieve.
    ///   - logger: Logger used for logging
    @inlinable
    public func waitUntilCodeScanSucceeded(
        environmentId: String,
        scanRunId: String,
        logger: Logger = AWSClient.loggingDisabled        
    ) async throws {
        let input = GetCodeScanInput(
            environmentId: environmentId, 
            scanRunId: scanRunId
        )
        try await self.waitUntilCodeScanSucceeded(input, logger: logger)
    }
